import { describe, it, expect } from "vitest";
import { cn } from "@/lib/utils";

describe("cn", () => {
  describe("basic merging", () => {
    it("should merge two class names into a space-separated string", () => {
      expect(cn("foo", "bar")).toBe("foo bar");
    });

    it("should merge multiple class names", () => {
      expect(cn("foo", "bar", "baz")).toBe("foo bar baz");
    });

    it("should return a single class name unchanged", () => {
      expect(cn("foo")).toBe("foo");
    });

    it("should return empty string when no arguments provided", () => {
      expect(cn()).toBe("");
    });
  });

  describe("conditional classes", () => {
    it("should include class when condition is true", () => {
      const active = true;
      expect(cn("base", active && "active")).toBe("base active");
    });

    it("should omit class when condition is false", () => {
      const active = false;
      expect(cn("base", active && "active")).toBe("base");
    });

    it("should handle ternary conditional classes", () => {
      expect(cn("base", true ? "yes" : "no")).toBe("base yes");
      expect(cn("base", false ? "yes" : "no")).toBe("base no");
    });

    it("should handle object syntax for conditional classes", () => {
      expect(cn({ "text-red-500": true, "text-blue-500": false })).toBe("text-red-500");
    });

    it("should include multiple true conditions", () => {
      expect(cn("base", true && "a", true && "b")).toBe("base a b");
    });
  });

  describe("falsy value handling", () => {
    it("should ignore false values", () => {
      expect(cn("base", false, "visible")).toBe("base visible");
    });

    it("should ignore undefined values", () => {
      expect(cn("base", undefined, "visible")).toBe("base visible");
    });

    it("should ignore null values", () => {
      expect(cn("base", null, "visible")).toBe("base visible");
    });

    it("should ignore empty string values", () => {
      expect(cn("base", "", "visible")).toBe("base visible");
    });

    it("should handle all falsy values together", () => {
      expect(cn(false, undefined, null, "", "real-class")).toBe("real-class");
    });

    it("should return empty string when all values are falsy", () => {
      expect(cn(false, undefined, null)).toBe("");
    });
  });

  describe("Tailwind conflict resolution", () => {
    it("should resolve conflicting text color classes — last one wins", () => {
      expect(cn("text-red-500", "text-blue-500")).toBe("text-blue-500");
    });

    it("should resolve conflicting padding classes — last one wins", () => {
      expect(cn("px-4", "px-2")).toBe("px-2");
    });

    it("should resolve conflicting background color classes", () => {
      expect(cn("bg-red-500", "bg-green-500")).toBe("bg-green-500");
    });

    it("should resolve conflicting font size classes", () => {
      expect(cn("text-sm", "text-lg")).toBe("text-lg");
    });

    it("should keep non-conflicting classes from both arguments", () => {
      const result = cn("flex items-center", "justify-between");
      expect(result).toContain("flex");
      expect(result).toContain("items-center");
      expect(result).toContain("justify-between");
    });

    it("should resolve conflicting margin classes", () => {
      expect(cn("m-4", "m-2")).toBe("m-2");
    });

    it("should resolve via conditional override pattern", () => {
      const isError = true;
      expect(cn("text-gray-500", isError && "text-red-500")).toBe("text-red-500");
    });

    it("should deduplicate identical class names", () => {
      expect(cn("flex", "flex")).toBe("flex");
    });
  });
});

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { exportToCSV } from "@/lib/csvExport";

describe("exportToCSV", () => {
  let mockAnchor: { href: string; download: string; click: ReturnType<typeof vi.fn> };
  let createElementSpy: ReturnType<typeof vi.spyOn>;
  let createObjectURLSpy: ReturnType<typeof vi.spyOn>;
  let revokeObjectURLSpy: ReturnType<typeof vi.spyOn>;

  beforeEach(() => {
    // Mock anchor element
    mockAnchor = { href: "", download: "", click: vi.fn() };
    createElementSpy = vi
      .spyOn(document, "createElement")
      .mockImplementation((tag: string) => {
        if (tag === "a") return mockAnchor as unknown as HTMLElement;
        return document.createElement(tag);
      });

    // Mock URL methods
    createObjectURLSpy = vi
      .spyOn(URL, "createObjectURL")
      .mockReturnValue("blob:mock-url");
    revokeObjectURLSpy = vi
      .spyOn(URL, "revokeObjectURL")
      .mockImplementation(() => {});
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  describe("early return guard", () => {
    it("should return early without creating any element when data is empty", () => {
      exportToCSV([], "test-file");
      expect(createElementSpy).not.toHaveBeenCalled();
      expect(createObjectURLSpy).not.toHaveBeenCalled();
      expect(mockAnchor.click).not.toHaveBeenCalled();
    });
  });

  describe("CSV structure", () => {
    it("should build the correct header row from object keys", () => {
      const data = [{ name: "Alice", score: 90 }];
      let capturedBlob: Blob | undefined;
      createObjectURLSpy.mockImplementation((blob: Blob) => {
        capturedBlob = blob;
        return "blob:mock-url";
      });

