function computeSummaryFromStages(stages: CandidateStage[]): Record<HiringStage, number> {
  const summary: Record<HiringStage, number> = {
    applied: 0,
    screened: 0,
    interview: 0,
    offer: 0,
    hired: 0,
    rejected: 0,
  };
  stages.forEach((s) => {
    if (summary[s.stage] !== undefined) {
      summary[s.stage]++;
    }
  });
  return summary;
}

