import { describe, it, expect } from "vitest";

// ---------------------------------------------------------------------------
// Types and pure functions extracted from JobDetailView stage filter logic
// ---------------------------------------------------------------------------
type HiringStage = "applied" | "screened" | "interview" | "offer" | "hired" | "rejected";

interface Result {
  resume_id: string;
  pending?: boolean;
  overall_score: number;
}

interface StageEntry {
  resume_id: string;
  stage: HiringStage;
}

function filterByStage(
  results: Result[],
  stageMap: Map<string, StageEntry>,
  stageFilter: HiringStage | null
): Result[] {
  return results.filter((r) => {
    if (!stageFilter) return true;
    const candidateStage = stageMap.get(r.resume_id)?.stage ?? "applied";
    return candidateStage === stageFilter;
  });
}

function computeStageCounts(
  results: Result[],
  stageMap: Map<string, StageEntry>,
  dismissed: Set<string>
): Record<string, number> {
  const stages = [
    "applied",
    "screened",
    "interview",
    "offer",
    "hired",
    "rejected",
  ] as const;
  const nonArchived = results.filter(
    (r) => !dismissed.has(r.resume_id) && !r.pending
  );
  return stages.reduce(
    (acc, stage) => {
      acc[stage] = nonArchived.filter(
        (r) => (stageMap.get(r.resume_id)?.stage ?? "applied") === stage
      ).length;
      return acc;
    },
    {} as Record<string, number>
  );
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
function makeResult(
  resume_id: string,
  overall_score = 80,
  pending = false
): Result {
  return { resume_id, overall_score, pending };
}

function makeEntry(resume_id: string, stage: HiringStage): StageEntry {
  return { resume_id, stage };
}

function makeMap(entries: StageEntry[]): Map<string, StageEntry> {
  const m = new Map<string, StageEntry>();
  entries.forEach((e) => m.set(e.resume_id, e));
  return m;
}

// ---------------------------------------------------------------------------
// filterByStage tests
// ---------------------------------------------------------------------------
describe("filterByStage", () => {
  it("should return all results when stageFilter is null", () => {
    const results = [makeResult("r1"), makeResult("r2"), makeResult("r3")];
    const stageMap = makeMap([
      makeEntry("r1", "applied"),
      makeEntry("r2", "screened"),
    ]);
    const filtered = filterByStage(results, stageMap, null);
    expect(filtered).toHaveLength(3);
  });

  it("should return only results matching the given stage", () => {
    const results = [makeResult("r1"), makeResult("r2"), makeResult("r3")];
    const stageMap = makeMap([
      makeEntry("r1", "screened"),
      makeEntry("r2", "screened"),
      makeEntry("r3", "interview"),
    ]);
    const filtered = filterByStage(results, stageMap, "screened");
    expect(filtered).toHaveLength(2);
    expect(filtered.map((r) => r.resume_id)).toEqual(["r1", "r2"]);
  });

  it("should treat candidates with no stageMap entry as applied", () => {
    const results = [makeResult("r1"), makeResult("r2")];
    // r2 has no entry — should be treated as "applied"
    const stageMap = makeMap([makeEntry("r1", "screened")]);
    const filtered = filterByStage(results, stageMap, "applied");
    expect(filtered).toHaveLength(1);
    expect(filtered[0].resume_id).toBe("r2");
  });

  it("should return empty array when no candidates match the filter", () => {
    const results = [makeResult("r1"), makeResult("r2")];
    const stageMap = makeMap([
      makeEntry("r1", "applied"),
      makeEntry("r2", "applied"),
    ]);
    const filtered = filterByStage(results, stageMap, "hired");
    expect(filtered).toHaveLength(0);
  });

  it("should correctly filter by rejected stage", () => {
    const results = [makeResult("r1"), makeResult("r2"), makeResult("r3")];
    const stageMap = makeMap([
      makeEntry("r1", "rejected"),
      makeEntry("r2", "applied"),
      makeEntry("r3", "rejected"),
    ]);
    const filtered = filterByStage(results, stageMap, "rejected");
    expect(filtered).toHaveLength(2);
    expect(filtered.map((r) => r.resume_id)).toEqual(["r1", "r3"]);
  });

  it("should handle an empty results array with any filter without error", () => {
    const filtered = filterByStage([], new Map(), "screened");
    expect(filtered).toHaveLength(0);
  });

  it("should handle an empty stageMap with a non-applied filter", () => {
    const results = [makeResult("r1"), makeResult("r2")];
    // All candidates default to "applied" — screened filter yields nothing
    const filtered = filterByStage(results, new Map(), "screened");
    expect(filtered).toHaveLength(0);
  });
});

// ---------------------------------------------------------------------------
// computeStageCounts tests
// ---------------------------------------------------------------------------
describe("computeStageCounts", () => {
  it("should count un-staged candidates as applied", () => {
    const results = [makeResult("r1"), makeResult("r2")];
    // No stageMap entries — both default to "applied"
    const counts = computeStageCounts(results, new Map(), new Set());
    expect(counts.applied).toBe(2);
    expect(counts.screened).toBe(0);
  });

  it("should exclude dismissed candidates from all counts", () => {
    const results = [makeResult("r1"), makeResult("r2"), makeResult("r3")];
    const stageMap = makeMap([
      makeEntry("r1", "applied"),
      makeEntry("r2", "applied"),
      makeEntry("r3", "applied"),
    ]);
    const dismissed = new Set<string>(["r2"]);
    const counts = computeStageCounts(results, stageMap, dismissed);
    expect(counts.applied).toBe(2);
  });

  it("should exclude pending candidates from all counts", () => {
    const results = [makeResult("r1", 80, false), makeResult("r2", 80, true)];
    const stageMap = makeMap([
      makeEntry("r1", "screened"),
      makeEntry("r2", "screened"),
    ]);
    const counts = computeStageCounts(results, stageMap, new Set());
    expect(counts.screened).toBe(1);
  });

  it("should exclude both dismissed and pending candidates", () => {
    const results = [
      makeResult("r1", 80, false),
      makeResult("r2", 80, true),
      makeResult("r3", 80, false),
    ];
    const stageMap = makeMap([
      makeEntry("r1", "interview"),
      makeEntry("r2", "interview"),
      makeEntry("r3", "interview"),
    ]);
    const dismissed = new Set<string>(["r3"]);
    const counts = computeStageCounts(results, stageMap, dismissed);
    // r2 is pending, r3 is dismissed — only r1 counts
    expect(counts.interview).toBe(1);
  });

  it("should return 0 for stages with no candidates", () => {
    const results = [makeResult("r1")];
    const stageMap = makeMap([makeEntry("r1", "hired")]);
    const counts = computeStageCounts(results, stageMap, new Set());
    expect(counts.applied).toBe(0);
    expect(counts.screened).toBe(0);
    expect(counts.interview).toBe(0);
    expect(counts.offer).toBe(0);
    expect(counts.hired).toBe(1);
    expect(counts.rejected).toBe(0);
  });

  it("should correctly count candidates spread across multiple stages", () => {
    const results = [
      makeResult("r1"),
      makeResult("r2"),
      makeResult("r3"),
      makeResult("r4"),
    ];
    const stageMap = makeMap([
      makeEntry("r1", "applied"),
      makeEntry("r2", "screened"),
      makeEntry("r3", "interview"),
      makeEntry("r4", "rejected"),
    ]);
    const counts = computeStageCounts(results, stageMap, new Set());
    expect(counts.applied).toBe(1);
    expect(counts.screened).toBe(1);
    expect(counts.interview).toBe(1);
    expect(counts.rejected).toBe(1);
    expect(counts.offer).toBe(0);
    expect(counts.hired).toBe(0);
  });

  it("should return all zeros when results array is empty", () => {
    const counts = computeStageCounts([], new Map(), new Set());
    expect(counts.applied).toBe(0);
    expect(counts.screened).toBe(0);
    expect(counts.interview).toBe(0);
    expect(counts.offer).toBe(0);
    expect(counts.hired).toBe(0);
    expect(counts.rejected).toBe(0);
  });
});

import { describe, it, expect } from "vitest";

// ---------------------------------------------------------------------------
// Canonical URL logic extracted from SeoHead.tsx (lines 26-28)
// ---------------------------------------------------------------------------
function buildCanonical(
  pageCanonical: string | undefined,
  globalCanonical: string | undefined,
  pathname: string
): string {
  const canonicalBase = (globalCanonical || "").replace(/\/$/, "");
  return pageCanonical || (canonicalBase ? `${canonicalBase}${pathname}` : "");
}

describe("buildCanonical", () => {
  describe("per-page canonical takes priority", () => {
    it("should return the per-page canonical as-is without appending pathname", () => {
      const result = buildCanonical(
        "https://example.com/custom-page",
        "https://example.com",
        "/settings"
      );
      expect(result).toBe("https://example.com/custom-page");
    });

    it("should prefer per-page canonical over global canonical + pathname combination", () => {
      const result = buildCanonical(
        "https://example.com/override",
        "https://site.com",
        "/jobs"
      );
      expect(result).toBe("https://example.com/override");
    });

    it("should return per-page canonical even when global canonical is undefined", () => {
      const result = buildCanonical("https://example.com/page", undefined, "/jobs");
      expect(result).toBe("https://example.com/page");
    });
  });

  describe("global canonical base URL + pathname", () => {
    it("should append the current pathname to the global canonical base URL", () => {
      const result = buildCanonical(undefined, "https://example.com", "/about");
      expect(result).toBe("https://example.com/about");
    });

    it("should strip trailing slash from global canonical before appending pathname", () => {
      const result = buildCanonical(undefined, "https://example.com/", "/pricing");
      expect(result).toBe("https://example.com/pricing");
    });

    it("should handle multiple trailing slashes on global canonical", () => {
      // Only one trailing slash is stripped by the single replace
      const result = buildCanonical(undefined, "https://example.com/", "/contact");
      expect(result).toBe("https://example.com/contact");
    });

    it("should handle root pathname /", () => {
      const result = buildCanonical(undefined, "https://example.com", "/");
      expect(result).toBe("https://example.com/");
    });

    it("should handle a nested pathname like /settings/billing", () => {
      const result = buildCanonical(
        undefined,
        "https://example.com",
        "/settings/billing"
      );
      expect(result).toBe("https://example.com/settings/billing");
    });
  });

  describe("empty / undefined fallbacks", () => {
    it("should return empty string when both pageCanonical and globalCanonical are undefined", () => {
      const result = buildCanonical(undefined, undefined, "/jobs");
      expect(result).toBe("");
    });

    it("should return empty string when both are empty strings", () => {
      const result = buildCanonical("", "", "/jobs");
      expect(result).toBe("");
    });

    it("should return empty string when pageCanonical is empty and globalCanonical is empty", () => {
      const result = buildCanonical("", "", "/");
      expect(result).toBe("");
    });

    it("should return empty string when globalCanonical is just a slash", () => {
      // After stripping trailing slash, canonicalBase becomes "" — falsy
      const result = buildCanonical(undefined, "/", "/page");
      expect(result).toBe("/page");
    });

    it("should treat an empty-string pageCanonical as falsy and fall back to global", () => {
      const result = buildCanonical("", "https://example.com", "/dashboard");
      expect(result).toBe("https://example.com/dashboard");
    });
  });

  describe("edge cases", () => {
    it("should handle globalCanonical with a path prefix", () => {
      const result = buildCanonical(
        undefined,
        "https://example.com/app",
        "/dashboard"
      );
      expect(result).toBe("https://example.com/app/dashboard");
    });

    it("should not double-slash when globalCanonical ends with slash and pathname starts with slash", () => {
      // The trailing slash is stripped from globalCanonical, so no double slash
      const result = buildCanonical(undefined, "https://example.com/", "/page");
      expect(result).toBe("https://example.com/page");
    });
  });
});

