// ---------------------------------------------------------------------------
// Contact extraction logic extracted from the resume parsed_json merging
// ---------------------------------------------------------------------------
function extractContact(parsed: unknown) {
  const p = parsed as Record<string, unknown> | null | undefined;
  const contact = p?.contact as Record<string, unknown> | null | undefined;
  return {
    candidate_email: (p?.email ?? contact?.email ?? null) as string | null,
    candidate_phone: (p?.phone ?? contact?.phone ?? null) as string | null,
    candidate_location: (p?.location ?? contact?.location ?? null) as string | null,
  };
}

describe("extractContact", () => {
  describe("top-level field extraction", () => {
    it("should extract email from top-level parsed.email", () => {
      const result = extractContact({ email: "alice@example.com" });
      expect(result.candidate_email).toBe("alice@example.com");
    });

    it("should extract phone from top-level parsed.phone", () => {
      const result = extractContact({ phone: "+1-555-0100" });
      expect(result.candidate_phone).toBe("+1-555-0100");
    });

    it("should extract location from top-level parsed.location", () => {
      const result = extractContact({ location: "New York, NY" });
      expect(result.candidate_location).toBe("New York, NY");
    });

    it("should extract all three fields from top-level when all are present", () => {
      const result = extractContact({
        email: "bob@example.com",
        phone: "555-1234",
        location: "San Francisco, CA",
      });
      expect(result.candidate_email).toBe("bob@example.com");
      expect(result.candidate_phone).toBe("555-1234");
      expect(result.candidate_location).toBe("San Francisco, CA");
    });
  });

  describe("nested contact field fallback", () => {
    it("should extract email from nested parsed.contact.email when top-level email is absent", () => {
      const result = extractContact({ contact: { email: "nested@example.com" } });
      expect(result.candidate_email).toBe("nested@example.com");
    });

    it("should extract phone from nested parsed.contact.phone when top-level phone is absent", () => {
      const result = extractContact({ contact: { phone: "555-9999" } });
      expect(result.candidate_phone).toBe("555-9999");
    });

    it("should extract location from nested parsed.contact.location when top-level location is absent", () => {
      const result = extractContact({ contact: { location: "Austin, TX" } });
      expect(result.candidate_location).toBe("Austin, TX");
    });

    it("should extract all three fields from nested contact when no top-level fields exist", () => {
      const result = extractContact({
        contact: {
          email: "c@example.com",
          phone: "000-0000",
          location: "Chicago, IL",
        },
      });
      expect(result.candidate_email).toBe("c@example.com");
      expect(result.candidate_phone).toBe("000-0000");
      expect(result.candidate_location).toBe("Chicago, IL");
    });
  });

  describe("top-level takes priority over nested contact", () => {
    it("should use top-level email over nested contact email", () => {
      const result = extractContact({
        email: "top@example.com",
        contact: { email: "nested@example.com" },
      });
      expect(result.candidate_email).toBe("top@example.com");
    });

    it("should use top-level phone over nested contact phone", () => {
      const result = extractContact({
        phone: "111-1111",
        contact: { phone: "999-9999" },
      });
      expect(result.candidate_phone).toBe("111-1111");
    });

    it("should use top-level location over nested contact location", () => {
      const result = extractContact({
        location: "Denver, CO",
        contact: { location: "Seattle, WA" },
      });
      expect(result.candidate_location).toBe("Denver, CO");
    });

    it("should mix top-level and nested fields independently", () => {
      // email from top-level, phone from nested, location missing entirely
      const result = extractContact({
        email: "mix@example.com",
        contact: { phone: "777-7777" },
      });
      expect(result.candidate_email).toBe("mix@example.com");
      expect(result.candidate_phone).toBe("777-7777");
      expect(result.candidate_location).toBeNull();
    });
  });

  describe("null and empty input handling", () => {
    it("should return null for all fields when parsed is null", () => {
      const result = extractContact(null);
      expect(result.candidate_email).toBeNull();
      expect(result.candidate_phone).toBeNull();
      expect(result.candidate_location).toBeNull();
    });

    it("should return null for all fields when parsed is undefined", () => {
      const result = extractContact(undefined);
      expect(result.candidate_email).toBeNull();
      expect(result.candidate_phone).toBeNull();
      expect(result.candidate_location).toBeNull();
    });

    it("should return null for all fields when parsed is an empty object", () => {
      const result = extractContact({});
      expect(result.candidate_email).toBeNull();
      expect(result.candidate_phone).toBeNull();
      expect(result.candidate_location).toBeNull();
    });

    it("should return null for fields not present even when other fields exist", () => {
      const result = extractContact({ email: "only@example.com" });
      expect(result.candidate_email).toBe("only@example.com");
      expect(result.candidate_phone).toBeNull();
      expect(result.candidate_location).toBeNull();
    });

    it("should return null for all fields when contact sub-object is empty", () => {
      const result = extractContact({ contact: {} });
      expect(result.candidate_email).toBeNull();
      expect(result.candidate_phone).toBeNull();
      expect(result.candidate_location).toBeNull();
    });
  });
});

import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen, fireEvent } from "@testing-library/react";
import StageTracker from "@/components/candidate/StageTracker";
import type { HiringStage } from "@/hooks/useStageTracker";

// ---------------------------------------------------------------------------
// date-fns mock — format() returns a predictable string
// ---------------------------------------------------------------------------
vi.mock("date-fns", () => ({
  format: (_date: Date, _fmt: string) => "Jan 15",
}));

// ---------------------------------------------------------------------------
// Helper: render StageTracker with sensible defaults
// ---------------------------------------------------------------------------
function renderTracker(overrides: {
  currentStage?: HiringStage;
  updatedAt?: string | null;
  onStageChange?: (stage: HiringStage) => void;
  disabled?: boolean;
}) {
  const props = {
    currentStage: overrides.currentStage ?? "applied",
    updatedAt: overrides.updatedAt ?? null,
    onStageChange: overrides.onStageChange ?? vi.fn(),
    disabled: overrides.disabled ?? false,
  };
  return render(<StageTracker {...props} />);
}

describe("StageTracker component", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe("stage labels rendering", () => {
    it("should render the Applied stage label", () => {
      renderTracker({ currentStage: "applied" });
      expect(screen.getByText("Applied")).toBeInTheDocument();
    });

    it("should render the Screened stage label", () => {
      renderTracker({ currentStage: "applied" });
      expect(screen.getByText("Screened")).toBeInTheDocument();
    });

    it("should render the Interview stage label", () => {
      renderTracker({ currentStage: "applied" });
      expect(screen.getByText("Interview")).toBeInTheDocument();
    });

    it("should render the Offer stage label", () => {
      renderTracker({ currentStage: "applied" });
      expect(screen.getByText("Offer")).toBeInTheDocument();
    });

    it("should render the Hired stage label", () => {
      renderTracker({ currentStage: "applied" });
      expect(screen.getByText("Hired")).toBeInTheDocument();
    });

    it("should render all 5 stage labels at once", () => {
      renderTracker({ currentStage: "screened" });
      const labels = ["Applied", "Screened", "Interview", "Offer", "Hired"];
      labels.forEach((label) => {
        expect(screen.getByText(label)).toBeInTheDocument();
      });
    });
  });

  describe("reject button", () => {
    it("should render the reject button (XCircle icon container)", () => {
      renderTracker({ currentStage: "applied" });
      // The reject button is the ghost icon Button wrapping XCircle
      // XCircle is a lucide icon rendered as an SVG — query by its parent button role
      const buttons = screen.getAllByRole("button");
      // 5 stage dots + 1 reject button = 6 buttons
      expect(buttons.length).toBeGreaterThanOrEqual(1);
    });

    it("should call onStageChange with 'rejected' when reject button is clicked", () => {
      const onStageChange = vi.fn();
      renderTracker({ currentStage: "applied", onStageChange });
      // The reject button is the last button rendered
      const buttons = screen.getAllByRole("button");
      const rejectButton = buttons[buttons.length - 1];
      fireEvent.click(rejectButton);
      expect(onStageChange).toHaveBeenCalledWith("rejected");
    });
  });

  describe("rejected state", () => {
    it("should show the Rejected badge when currentStage is rejected", () => {
      renderTracker({ currentStage: "rejected" });
      expect(screen.getByText("Rejected")).toBeInTheDocument();
    });

    it("should NOT show the Rejected badge when currentStage is not rejected", () => {
      renderTracker({ currentStage: "applied" });
      expect(screen.queryByText("Rejected")).not.toBeInTheDocument();
    });
  });

  describe("stage dot click interactions", () => {
    it("should call onStageChange with the correct stage when a stage dot is clicked", () => {
      const onStageChange = vi.fn();
      renderTracker({ currentStage: "applied", onStageChange });
      // There are 5 stage dot buttons — get all buttons
      const buttons = screen.getAllByRole("button");
      // The first 5 buttons are stage dots (applied=0, screened=1, interview=2, offer=3, hired=4)
      // Click the second dot (screened)
      fireEvent.click(buttons[1]);
      expect(onStageChange).toHaveBeenCalledWith("screened");
    });

    it("should call onStageChange with 'applied' when the first dot is clicked", () => {
      const onStageChange = vi.fn();
      renderTracker({ currentStage: "screened", onStageChange });
      const buttons = screen.getAllByRole("button");
      fireEvent.click(buttons[0]);
      expect(onStageChange).toHaveBeenCalledWith("applied");
    });

    it("should call onStageChange with 'interview' when the third dot is clicked", () => {
      const onStageChange = vi.fn();
      renderTracker({ currentStage: "applied", onStageChange });
      const buttons = screen.getAllByRole("button");
      fireEvent.click(buttons[2]);
      expect(onStageChange).toHaveBeenCalledWith("interview");
    });

    it("should call onStageChange with 'offer' when the fourth dot is clicked", () => {
      const onStageChange = vi.fn();
      renderTracker({ currentStage: "applied", onStageChange });
      const buttons = screen.getAllByRole("button");
      fireEvent.click(buttons[3]);
      expect(onStageChange).toHaveBeenCalledWith("offer");
    });

    it("should call onStageChange with 'hired' when the fifth dot is clicked", () => {
      const onStageChange = vi.fn();
      renderTracker({ currentStage: "applied", onStageChange });
      const buttons = screen.getAllByRole("button");
      fireEvent.click(buttons[4]);
      expect(onStageChange).toHaveBeenCalledWith("hired");
    });
  });

  describe("updatedAt timestamp", () => {
    it("should show formatted date when updatedAt is provided", () => {
      renderTracker({
        currentStage: "screened",
        updatedAt: "2024-01-15T10:00:00Z",
      });
      // date-fns format is mocked to return "Jan 15"
      expect(screen.getByText(/Updated Jan 15/)).toBeInTheDocument();
    });

    it("should NOT show timestamp when updatedAt is null", () => {
      renderTracker({ currentStage: "applied", updatedAt: null });
      expect(screen.queryByText(/Updated/)).not.toBeInTheDocument();
    });

    it("should NOT show timestamp when updatedAt is undefined", () => {
      renderTracker({ currentStage: "applied", updatedAt: undefined });
      expect(screen.queryByText(/Updated/)).not.toBeInTheDocument();
    });
  });

  describe("disabled prop", () => {
    it("should disable all stage dot buttons when disabled is true", () => {
      renderTracker({ currentStage: "applied", disabled: true });
      const buttons = screen.getAllByRole("button");
      // Stage dot buttons are plain <button> elements — verify they have the disabled attribute
      // The reject Button is a shadcn Button which also respects disabled
      buttons.forEach((btn) => {
        expect(btn).toBeDisabled();
      });
    });

    it("should NOT disable buttons when disabled is false", () => {
      renderTracker({ currentStage: "applied", disabled: false });
      const buttons = screen.getAllByRole("button");
      buttons.forEach((btn) => {
        expect(btn).not.toBeDisabled();
      });
    });

    it("should not call onStageChange when a stage dot is clicked and disabled is true", () => {
      const onStageChange = vi.fn();
      renderTracker({ currentStage: "applied", onStageChange, disabled: true });
      const buttons = screen.getAllByRole("button");
      // Try clicking the first stage dot
      fireEvent.click(buttons[0]);
      // Disabled buttons should not fire click handlers in the browser,
      // but jsdom does fire them. The component passes disabled to <button disabled>
      // which prevents clicks in browsers. We test that the button is disabled attribute.
      expect(buttons[0]).toBeDisabled();
    });
  });
});

