import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { exportToCSV } from "@/lib/csvExport";

// ---------------------------------------------------------------------------
// Helper: capture the CSV text passed to `new Blob([content], ...)`.
// jsdom's Blob doesn't implement .text(), so we track content at construction.
// ---------------------------------------------------------------------------

let lastBlobContent: string = "";

const OriginalBlob = globalThis.Blob;

// Override Blob to intercept and store the content string
class MockBlob extends OriginalBlob {
  constructor(parts?: BlobPart[], options?: BlobPropertyBag) {
    super(parts, options);
    if (parts && parts.length > 0 && typeof parts[0] === "string") {
      lastBlobContent = parts[0];
    }
  }
}

describe("exportToCSV", () => {
  let mockAnchor: { href: string; download: string; click: ReturnType<typeof vi.fn> };
  let createElementSpy: ReturnType<typeof vi.spyOn>;
  let createObjectURLSpy: ReturnType<typeof vi.spyOn>;
  let revokeObjectURLSpy: ReturnType<typeof vi.spyOn>;

  beforeEach(() => {
    // Reset captured blob content
    lastBlobContent = "";

    // Swap in our MockBlob to capture CSV text
    globalThis.Blob = MockBlob as unknown as typeof Blob;

    // jsdom does not define URL.createObjectURL / revokeObjectURL — define them first
    if (!URL.createObjectURL) {
      URL.createObjectURL = vi.fn(() => "blob:mock-url");
    }
    if (!URL.revokeObjectURL) {
      URL.revokeObjectURL = vi.fn();
    }

    // Mock anchor element
    mockAnchor = { href: "", download: "", click: vi.fn() };
    createElementSpy = vi
      .spyOn(document, "createElement")
      .mockImplementation((tag: string) => {
        if (tag === "a") return mockAnchor as unknown as HTMLElement;
        return document.createElement(tag);
      });

    // Spy on the (now-existing) URL methods
    createObjectURLSpy = vi
      .spyOn(URL, "createObjectURL")
      .mockReturnValue("blob:mock-url");
    revokeObjectURLSpy = vi
      .spyOn(URL, "revokeObjectURL")
      .mockImplementation(() => {});
  });

  afterEach(() => {
    // Restore original Blob
    globalThis.Blob = OriginalBlob;
    vi.restoreAllMocks();
  });

  describe("early return guard", () => {
    it("should return early without creating any element when data is empty", () => {
      exportToCSV([], "test-file");
      expect(createElementSpy).not.toHaveBeenCalled();
      expect(createObjectURLSpy).not.toHaveBeenCalled();
      expect(mockAnchor.click).not.toHaveBeenCalled();
    });
  });

  describe("CSV structure", () => {
    it("should build the correct header row from object keys", () => {
      const data = [{ name: "Alice", score: 90 }];
      exportToCSV(data, "test");
      const lines = lastBlobContent.split("\n");
      expect(lines[0]).toBe('"name","score"');
    });

    it("should write one data row per record after the header", () => {
      const data = [
        { name: "Alice", score: 90 },
        { name: "Bob", score: 80 },
      ];
      exportToCSV(data, "test");
      const lines = lastBlobContent.split("\n");
      // header + 2 data rows
      expect(lines).toHaveLength(3);
    });

    it("should quote all values in the data rows", () => {
      const data = [{ name: "Alice", score: 90 }];
      exportToCSV(data, "test");
      const lines = lastBlobContent.split("\n");
      const dataRow = lines[1];
      // Every value should be wrapped in double quotes
      expect(dataRow).toBe('"Alice","90"');
    });

    it("should escape double quotes inside values by doubling them", () => {
      const data = [{ description: 'He said "hello"' }];
      exportToCSV(data, "test");
      const lines = lastBlobContent.split("\n");
      const dataRow = lines[1];
      // Double quotes inside value become ""
      expect(dataRow).toBe('"He said ""hello"""');
    });

    it("should handle multiple double quotes in a single value", () => {
      const data = [{ val: '"a" and "b"' }];
      exportToCSV(data, "test");
      const lines = lastBlobContent.split("\n");
      expect(lines[1]).toBe('"""a"" and ""b"""');
    });
  });

  describe("null / undefined handling", () => {
    it("should render null values as empty string inside quotes", () => {
      const data = [{ name: null, score: 42 }];
      exportToCSV(data as unknown as Record<string, unknown>[], "test");
      const lines = lastBlobContent.split("\n");
      const dataRow = lines[1];
      expect(dataRow).toBe('"","42"');
    });

    it("should render undefined values as empty string inside quotes", () => {
      const data = [{ name: undefined, score: 42 }];
      exportToCSV(data as unknown as Record<string, unknown>[], "test");
      const lines = lastBlobContent.split("\n");
      const dataRow = lines[1];
      expect(dataRow).toBe('"","42"');
    });

    it("should handle a row where all values are null", () => {
      const data = [{ a: null, b: null }];
      exportToCSV(data as unknown as Record<string, unknown>[], "test");
      const lines = lastBlobContent.split("\n");
      expect(lines[1]).toBe('"",""');
    });
  });

  describe("download mechanics", () => {
    it("should call URL.createObjectURL with a Blob", () => {
      exportToCSV([{ x: 1 }], "report");
      expect(createObjectURLSpy).toHaveBeenCalledTimes(1);
      expect(createObjectURLSpy.mock.calls[0][0]).toBeInstanceOf(OriginalBlob);
    });

    it("should set the anchor href to the blob URL", () => {
      exportToCSV([{ x: 1 }], "report");
      expect(mockAnchor.href).toBe("blob:mock-url");
    });

    it("should click the anchor element to trigger download", () => {
      exportToCSV([{ x: 1 }], "report");
      expect(mockAnchor.click).toHaveBeenCalledTimes(1);
    });

    it("should call URL.revokeObjectURL after clicking", () => {
      exportToCSV([{ x: 1 }], "report");
      expect(revokeObjectURLSpy).toHaveBeenCalledTimes(1);
      expect(revokeObjectURLSpy).toHaveBeenCalledWith("blob:mock-url");
    });

    it("should set the download filename with today's ISO date appended", () => {
      const todayStr = new Date().toISOString().slice(0, 10);
      exportToCSV([{ x: 1 }], "my-report");
      expect(mockAnchor.download).toBe(`my-report-${todayStr}.csv`);
    });

    it("should include the exact provided filename prefix in the download attribute", () => {
      exportToCSV([{ x: 1 }], "candidates-export");
      expect(mockAnchor.download).toMatch(/^candidates-export-/);
      expect(mockAnchor.download).toMatch(/\.csv$/);
    });
  });
});

